if(pg==='stories')return oShell('office/stories',`${head('Stories','Case studies, origin stories and testimonials, with permission status.',`<button class="btn primary" data-act="toast:New story opens the editor.">${ic('plus',18,'',2.2)}New story</button>`)}<div class="cardgrid">${STO[org()].map(s=>`<article class="card"><span class="tag" style="justify-self:start">${s[1]}</span><h3 style="font:600 22px/1.25 'Newsreader',serif">${s[0]}</h3><p>${s[2]}</p><div class="foot">${ic('map',14)}${s[3]}<span style="margin-left:auto">${s[4]?`<span class="pill blue" style="height:22px">${ic('check',12,'',2.6)}Consent</span>`:`<span class="pill warn" style="height:22px">${ic('alert',12)}Ask consent</span>`}</span></div></article>`).join('')}</div>`,[['Office'],['Stories']]);
